const $=s=>document.querySelector(s);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const scenario=window.UxdScenario.get();
const MAX=10*1024*1024;
let file=null,used=false,busy=false,epoch=0;
const models={vision:['Image'],audio:['Audio'],text:[],unknown:['Image','Audio']};
const endpoints=()=>JSON.parse(sessionStorage.getItem('endpoints')||'[{"name":"Whisper transcription","url":"https://whisper.example.test/v1","asr":true}]');
function alertText(t,kind='error'){ $('#notice').innerHTML=t?`<div class="alert ${kind}" role="alert">${esc(t)}</div>`:''; }
function reset(){epoch++;busy=false;used=false;file=null;$('#chat').innerHTML='<div class="empty"><h2>What would you like to explore?</h2><p>Add an image or audio file alongside your prompt.<br>Responses appear here as text.</p></div>';$('#attachment').innerHTML='';$('#prompt').value='';alertText('');update();}
function update(){const types=models[$('#model').value];$('#image-controls').hidden=!types.includes('Image');$('#audio-controls').hidden=!types.includes('Audio');$('#caps').textContent=types.length?'Text + '+types.join(' / '):'Text only';const list=scenario==='no-asr'?[]:endpoints().filter(x=>x.asr);$('#asr').innerHTML=list.length?list.map(x=>`<option>${esc(x.name)}</option>`).join(''):'<option value="">No transcription endpoints</option>';$('#asr-help').hidden=list.length>0;$('#send').disabled=busy|| (!!file&&file.kind==='Audio'&&!list.length);$('#sample-image').disabled=used||busy;$('#sample-audio').disabled=used||busy;$('#image-file').disabled=used||busy;$('#audio-file').disabled=used||busy;$('#limit').textContent=used?'This conversation already contains a file. Start a new conversation to attach another.':'One image or one audio file per conversation. JPG, PNG, WAV or MP3, up to 10 MB.';}
function attach(f,kind){if(used)return alertText('Only one image or audio file is allowed per conversation. Start a new conversation.');if(file)return alertText('Remove the current attachment before selecting another.');if(!f.size)return alertText('This file is empty. Choose a file with content.');if(f.size>MAX)return alertText('File exceeds the 10 MB limit. Choose a smaller file.');const allowed=kind==='Image'?['image/jpeg','image/png']:['audio/wav','audio/x-wav','audio/mpeg'];if(!allowed.includes(f.type))return alertText('Unsupported format. Use JPG or PNG for images, WAV or MP3 for audio. PDF belongs in Upload files.');file={name:f.name,kind,url:f instanceof File?URL.createObjectURL(f):null};$('#attachment').innerHTML=`<div class="attachment">${kind==='Image'?(file.url?`<img src="${file.url}" alt="Uploaded image preview">`:'<span aria-label="Sample image">▧ Mountain landscape</span>'):'<span>♫ Audio file</span>'}<span>${esc(f.name)} · Ready</span><button id="remove-file" type="button">Remove</button></div>`;$('#remove-file').onclick=()=>{file=null;$('#attachment').innerHTML='';update();};alertText('');update();}
async function send(){if(busy)return;if(!$('#prompt').value.trim()&&!file)return alertText('Enter a prompt or attach a file.');if(file?.kind==='Audio'&&!$('#asr').value)return alertText('Register a transcription model in AI Asset Endpoints before submitting audio.');const turn=epoch;busy=true;update();const pending=file;const prompt=$('#prompt').value.trim();$('#chat .empty')?.remove();$('#chat').insertAdjacentHTML('beforeend',`<div class="message"><strong>You</strong>${esc(prompt)}${pending?`<div class="attachment">${pending.kind==='Image'&&pending.url?`<img src="${pending.url}" alt="Submitted image">`:pending.kind==='Image'?'▧ Mountain landscape':'♫'} ${esc(pending.name)}</div>`:''}</div>`);const stages=pending?(pending.kind==='Audio'?['Uploading audio…','Transcribing audio…','Generating text response…']:['Uploading image…','Processing image…']):['Generating text response…'];for(const stage of stages){alertText(stage,'');await new Promise(r=>setTimeout(r,350));if(turn!==epoch)return;}if(pending&&$('#model').value==='unknown'){alertText('This model rejected the image input. Choose a vision-capable model or remove the file.');busy=false;update();return;}const response=pending?.kind==='Audio'?'Transcription: “Please summarize the customer feedback.”\n\nSummary: Customers value fast setup and clearer documentation. Prioritize onboarding guidance.':pending?'The image shows a mountain landscape with a lake in the foreground. The snow-covered peaks contrast with the blue water.':'I can help explore that prompt. This is a simulated text response.';$('#chat').insertAdjacentHTML('beforeend',`<div class="message response"><strong>Assistant</strong>${esc(response).replace(/\n/g,'<br>')}</div>`);used=used||!!pending;file=null;busy=false;$('#attachment').innerHTML='';$('#prompt').value='';alertText('');update();}
if($('#model')){
 $('#model').onchange=()=>{if(file&&!models[$('#model').value].includes(file.kind)){file=null;$('#attachment').innerHTML='';alertText('Attachment removed because the selected model does not support that input.','warning');}update();};$('#new-chat').onclick=reset;$('#send').onclick=send;
 $('#image-file').onchange=e=>{if(e.target.files[0])attach(e.target.files[0],'Image');e.target.value='';};$('#audio-file').onchange=e=>{if(e.target.files[0])attach(e.target.files[0],'Audio');e.target.value='';};
 $('#sample-image').onclick=()=>attach({name:'mountain-lake.png',size:240000,type:'image/png'},'Image');$('#sample-audio').onclick=()=>attach({name:'customer-feedback.wav',size:720000,type:'audio/wav'},'Audio');$('#audio-model').onclick=()=>{$('#model').value='audio';$('#model').onchange();};reset();
 if(['audio-result','no-asr','asr-error','empty-transcription'].includes(scenario)){$('#model').value='audio';update();}
 if(scenario==='image-result'||scenario==='audio-result'){const audio=scenario==='audio-result';$('#chat').innerHTML=`<div class="message"><strong>You</strong>${audio?'Summarize this recording.<div class="attachment">♫ customer-feedback.wav</div>':'Describe this image.<div class="attachment">▧ Mountain landscape · mountain-lake.png</div>'}</div><div class="message response"><strong>Assistant</strong>${audio?'Transcription: “Please summarize the customer feedback.”<p>Customers value fast setup. Improve onboarding documentation.</p>':'The image shows snow-covered peaks above a blue mountain lake.'}</div>`;used=true;update();}
 if(scenario==='asr-error'||scenario==='empty-transcription'){attach({name:'recording.wav',size:5000,type:'audio/wav'},'Audio');alertText(scenario==='asr-error'?'Transcription endpoint is unreachable. Check the endpoint and retry. No prompt was sent to the chat model.':'No speech detected. Remove this audio and choose a recording containing speech. No prompt was sent to the chat model.');if(scenario==='asr-error'){const retry=document.createElement('button');retry.textContent='Retry transcription';retry.id='retry-transcription';retry.onclick=send;$('#notice').append(retry);}}
 if(scenario==='unknown-capabilities'){$('#model').value='unknown';update();attach({name:'mountain-lake.png',size:4000,type:'image/png'},'Image');alertText('This model rejected image input. Choose a vision-capable model or remove the file.');}
}else{
 function render(){const list=scenario==='empty'&&!sessionStorage.getItem('endpoints')?[]:endpoints();$('#rows').innerHTML=list.map((x,i)=>`<tr><td><strong>${esc(x.name)}</strong><br><span class="muted">${esc(x.url)}</span></td><td>Available</td><td><label><input type="checkbox" data-endpoint="${i}" ${x.asr?'checked':''}> Audio transcription (ASR)</label></td></tr>`).join('');$('#no-endpoints').hidden=list.length>0;document.querySelectorAll('[data-endpoint]').forEach(el=>el.onchange=()=>{list[el.dataset.endpoint].asr=el.checked;sessionStorage.setItem('endpoints',JSON.stringify(list));alertText('Endpoint capability updated. The Playground audio model list is ready.','');});}
 $('#register').onclick=()=>$('#register-dialog').showModal();$('#cancel').onclick=()=>$('#register-dialog').close();$('#register-form').onsubmit=e=>{e.preventDefault();const list=scenario==='empty'&&!sessionStorage.getItem('endpoints')?[]:endpoints();list.push({name:$('#endpoint-name').value,url:$('#endpoint-url').value,asr:$('#endpoint-asr').checked});sessionStorage.setItem('endpoints',JSON.stringify(list));$('#register-dialog').close();render();alertText('AI Asset registered. ASR endpoints are now selectable in the Playground.','');};render();if(scenario==='load-error'){ $('#table').hidden=true;alertText('Unable to load AI Asset Endpoints. Check your connection and retry.');$('#retry').hidden=false;$('#retry').onclick=()=>{location.href='endpoints.html';};}
}
